/** Per-key derived state cache and the big-endian word read shared by the AES and SHA-1 cores. */
export function readWord(bytes, offset) {
    return (((bytes[offset] << 24) |
        (bytes[offset + 1] << 16) |
        (bytes[offset + 2] << 8) |
        bytes[offset + 3]) >>>
        0);
}
